questions.starter:
// mergeSettings(defaults, ...overrides)
// Spread defaults and all overrides into one object

const defaults = { theme: 'light', fontSize: 14, lang: 'en' };
const userPrefs = { theme: 'dark' };
const sessionPrefs = { fontSize: 18 };

// Call and log result

questions.solution:
function mergeSettings(defaults, ...overrides) {
  let result = { ...defaults };
  for (const override of overrides) {
    result = { ...result, ...override };
  }
  return result;
}

const defaults = { theme: 'light', fontSize: 14, lang: 'en' };
const userPrefs = { theme: 'dark' };
const sessionPrefs = { fontSize: 18 };

const final = mergeSettings(defaults, userPrefs, sessionPrefs);
console.log(final);

questions.starter:
// summarize(...items) — rest parameter
// Returns {count, total, names}

// Call with 3 product objects and log result

questions.solution:
function summarize(...items) {
  return {
    count: items.length,
    total: items.reduce((sum, item) => sum + item.price, 0),
    names: items.map(item => item.name)
  };
}

const result = summarize(
  { name: 'Earbuds', price: 4500 },
  { name: 'Cable', price: 600 },
  { name: 'Case', price: 1200 }
);

console.log(result);

